window.MG_LAZY_DATA["data/lazy/owner-courses/c101-6582f76be9d815c4.json"]={sha256:"6582f76be9d815c4135247dded758d7be64657bdc904e38702b2332dd2655506",value:{"id":"c101","title":"Alvin 載人科學潛器","titleEn":"Alvin human-occupied research submersible","category":"marine","summary":"以Alvin公開科學任務為背景，拆解浮力、縱傾、觀測幾何、樣本識別及資料驗證，理解深海研究平台如何服務科學問題。","summaryEn":"Use Alvin’s public science mission to study buoyancy, trim, viewing geometry, sample identity and data verification, linking an ocean platform to scientific questions.","scope":"12道紙上與示意模型任務，數值均為明示教學假設；不提供耐壓艙設計、生命維持規格、載人試驗、真實下潛計畫或操作許可。","scopeEn":"Twelve paper and schematic-model tasks with explicitly hypothetical values. No pressure-hull design, life-support specifications, crewed tests, actual dive planning or operating authorization.","contentStatus":"reviewable-educational-curriculum","sourceIds":["v6-alvin-history","v6-alvin-systems","v6-alvin-verification"],"diagram":{"type":"submarine","labels":["科學需求","浮力與配平","觀測與取樣","通訊與定位","資料證據"],"labelsEn":["Science requirements","Buoyancy and trim","Observation and sampling","Communication and positioning","Data evidence"],"original":true,"notToScale":true},"depth":4,"stages":[{"id":"c101-stage01","order":1,"title":"科學目的與靜力模型","titleEn":"Science purpose and static models","description":"把觀測需求連到壓差、浮力與力矩，區分平台功能與科學目的。","descriptionEn":"Connect observation needs to pressure difference, buoyancy and moments, separating platform function from science purpose.","route":"原創概念學習路線；工序編號是教學順序，不是原廠連續製造或操作程序。","routeEn":"An original conceptual learning route; numbering indicates teaching order, not a continuous manufacturer production or operating procedure.","steps":[{"id":"c101-v6-01","order":1,"sequence":1,"simulationOnly":true,"estimatedMinutes":18,"prerequisiteIds":[],"sourceIds":["v6-alvin-systems","v6-alvin-verification"],"title":"把科學問題轉成觀測需求","titleEn":"Turn a science question into observation requirements","objective":"定義潛器要取得的資料，而非只列設備。","objectiveEn":"Define the required data rather than merely listing instruments.","instruction":"設定虛構任務：比較兩處海底岩石外觀。列出影像、樣本識別、位置及時間四欄，說明每欄如何回答問題；不規劃真實下潛。","instructionEn":"Set a fictional mission comparing rock appearance at two seafloor sites. List imagery, sample identity, position and time, explaining how each answers the question. Do not plan an actual dive.","observation":"缺少位置或樣本識別的照片，難以連回同一觀測對象。","observationEn":"A photograph without location or sample identity is difficult to connect to its observation target.","failure":"把相機解析度當成整個任務成功標準，忽略資料脈絡。","failureEn":"Treating camera resolution as the entire success criterion ignores data context.","check":"每項資料均對應科學問題，且有識別與時間欄位。","checkEn":"Each datum maps to the science question and has identity and time fields.","knowledge":[{"id":"c101-v6-01-k1","title":"需求分配","titleEn":"Requirements allocation","text":"科學目的必須轉成可收集、可追溯的資料。","textEn":"A scientific purpose must become collectible, traceable data."},{"id":"c101-v6-01-k2","title":"任務邊界","titleEn":"Mission boundary","text":"教育案例只討論資料需求，不授權現場操作。","textEn":"The educational case addresses data requirements, not operational authorization."}],"quiz":{"question":"要把岩石照片與實體樣本對上，最缺不得的是什麼？","questionEn":"What is essential for matching a rock photograph to its physical sample?","options":["只依相近拍攝時間猜測配對","只依容器擺放順序配對","共同樣本識別碼與記錄"],"optionsEn":["Infer the pairing only from similar capture times","Match only by container placement order","A shared sample identifier and record"],"answer":2,"explanation":"共同識別碼維持影像與樣本間的關聯。","explanationEn":"A shared identifier preserves the image-to-sample relationship."}},{"id":"c101-v6-02","order":2,"sequence":2,"simulationOnly":true,"estimatedMinutes":18,"prerequisiteIds":["c101-v6-01"],"sourceIds":["v6-alvin-systems"],"title":"區分水深與壓差","titleEn":"Distinguish depth from pressure difference","objective":"用靜水概念標記外部與內部環境。","objectiveEn":"Use hydrostatics to label exterior and interior environments.","instruction":"畫一個封閉教學球體，分別標示外部水壓及內部壓力。以p外=p表面+ρgh比較h與2h的水柱貢獻；保持ρ與g不變，不計算艙壁厚度。","instructionEn":"Sketch a closed teaching sphere and label external and internal pressures. Use p_external=p_surface+ρgh to compare water-column contributions at h and 2h with constant density and gravity. Do not calculate wall thickness.","observation":"加倍深度使水柱壓力項加倍，但不使含表面壓力的絕對壓力恰好加倍。","observationEn":"Doubling depth doubles the water-column term, not necessarily the absolute pressure including surface pressure.","failure":"混用絕對壓力與壓差，會使載荷敘述不清。","failureEn":"Mixing absolute pressure with differential pressure obscures the load definition.","check":"圖上同時標出內壓、外壓及兩者差，寫明模型假設。","checkEn":"Label internal, external and differential pressures and state the assumptions.","knowledge":[{"id":"c101-v6-02-k1","title":"靜水壓力","titleEn":"Hydrostatic pressure","text":"在密度近似固定時，水柱壓力隨深度線性增加。","textEn":"With approximately constant density, water-column pressure grows linearly with depth."},{"id":"c101-v6-02-k2","title":"壓差","titleEn":"Differential pressure","text":"結構兩側環境的差異決定相應載荷問題。","textEn":"The difference between environments on either side defines the corresponding load problem."}],"quiz":{"question":"將h變為2h，哪一項恰好加倍？","questionEn":"When h becomes 2h, which term doubles exactly in this model?","options":["內部壓力必然","ρgh水柱項","所有絕對壓力"],"optionsEn":["The internal pressure necessarily","The ρgh water-column term","Every absolute pressure"],"answer":1,"explanation":"表面壓力項不隨水深加倍。","explanationEn":"The surface-pressure term does not double with depth."}},{"id":"c101-v6-03","order":3,"sequence":3,"simulationOnly":true,"estimatedMinutes":18,"prerequisiteIds":["c101-v6-02"],"sourceIds":["v6-alvin-systems"],"title":"建立浮力與重量帳","titleEn":"Build a buoyancy and weight balance","objective":"以排水體積與總質量判斷淨垂直力。","objectiveEn":"Use displaced volume and total mass to determine net vertical force.","instruction":"使用紙上假設ρ=1、g=1、排水體積V=12、質量m=10，算B−W。再加入3單位質量而不改體積，重新判讀；這不是Alvin的實際數值。","instructionEn":"Use paper assumptions ρ=1, g=1, displaced volume V=12 and mass m=10 to compute B−W. Add 3 mass units without changing volume and reassess. These are not Alvin’s actual values.","observation":"初始淨力為+2，增加載重後變成−1。","observationEn":"The initial net force is +2 and becomes −1 after adding the load.","failure":"用物體外觀大小代替實際排水體積，或漏算工具重量，都會改變判定。","failureEn":"Substituting apparent size for displaced volume or omitting tool mass changes the result.","check":"兩種狀態各寫出浮力、重量與淨力符號。","checkEn":"Record buoyancy, weight and net-force sign for both states.","knowledge":[{"id":"c101-v6-03-k1","title":"阿基米德原理","titleEn":"Archimedes’ principle","text":"浮力等於排開流體的重量。","textEn":"Buoyancy equals the weight of displaced fluid."},{"id":"c101-v6-03-k2","title":"載荷清單","titleEn":"Payload inventory","text":"新增樣本與工具會改變質量帳，未必等量增加排水體積。","textEn":"Samples and tools change mass without necessarily adding proportional displaced volume."}],"quiz":{"question":"此模型增加3單位質量後，淨力為何？","questionEn":"After adding 3 mass units in this model, what is the net force?","options":["−1，向下","+2，向上","0，必定中性"],"optionsEn":["−1, downward","+2, upward","0, necessarily neutral"],"answer":0,"explanation":"浮力12不變，重量由10變13，淨力為−1。","explanationEn":"Buoyancy stays 12 while weight becomes 13, giving −1."}},{"id":"c101-v6-04","order":4,"sequence":4,"simulationOnly":true,"estimatedMinutes":18,"prerequisiteIds":["c101-v6-03"],"sourceIds":["v6-alvin-systems"],"title":"用力矩理解縱傾","titleEn":"Understand trim through moments","objective":"分開判斷中性浮力與姿態平衡。","objectiveEn":"Separate neutral buoyancy from attitude balance.","instruction":"画側視圖，讓總浮力與重量相等，但兩作用線前後錯開。標出可能的轉動方向，再將一個小教學載荷沿前後移動，觀察力矩符號如何改變。","instructionEn":"Draw a side view with equal buoyancy and weight but fore-aft separation of their lines of action. Mark the possible rotation, then move a small teaching load along the vehicle and examine the moment sign.","observation":"垂直合力為零時，仍可能存在使潛器俯仰的力矩。","observationEn":"Zero vertical resultant can coexist with a pitching moment.","failure":"只檢查重量等於浮力，不能證明姿態已平衡。","failureEn":"Checking weight equals buoyancy alone does not establish attitude equilibrium.","check":"同時列出合力與合力矩兩個條件。","checkEn":"State both force and moment equilibrium conditions.","knowledge":[{"id":"c101-v6-04-k1","title":"浮心與重心","titleEn":"Centers of buoyancy and mass","text":"兩者的相對位置影響姿態回應。","textEn":"Their relative locations influence attitude response."},{"id":"c101-v6-04-k2","title":"力偶","titleEn":"Force couple","text":"大小相等、方向相反但作用線不同的力可形成力偶。","textEn":"Equal opposite forces on different lines can form a couple."}],"quiz":{"question":"浮力等於重量但作用線錯開，能否保證不轉動？","questionEn":"If buoyancy equals weight but the lines differ, is no rotation guaranteed?","options":["能，合力零就足夠","只有相機關閉才不能","不能，還要檢查力矩"],"optionsEn":["Yes; zero resultant force is sufficient","Only if the camera is off","No; moments must also be checked"],"answer":2,"explanation":"平移與轉動是不同平衡條件。","explanationEn":"Translational and rotational equilibrium are separate conditions."}}]},{"id":"c101-stage02","order":2,"title":"浮材、能量與取樣介面","titleEn":"Buoyancy material, energy and sampling interfaces","description":"以公開功能介紹和原創案例，檢查材料、照明及工具的相互限制。","descriptionEn":"Use public functions and original examples to examine material, lighting and tool constraints.","route":"原創概念學習路線；工序編號是教學順序，不是原廠連續製造或操作程序。","routeEn":"An original conceptual learning route; numbering indicates teaching order, not a continuous manufacturer production or operating procedure.","steps":[{"id":"c101-v6-05","order":1,"sequence":5,"simulationOnly":true,"estimatedMinutes":18,"prerequisiteIds":["c101-v6-04"],"sourceIds":["v6-alvin-systems"],"title":"比較浮材的功能與限制","titleEn":"Compare buoyancy-material functions and limits","objective":"區分低密度與環境耐受的證據。","objectiveEn":"Separate low density from environmental qualification.","instruction":"依WHOI公開介紹畫浮材、框架與附件的功能圖。對兩種假設材料建立密度、吸水或壓縮行為、固定介面三欄；沒有公開資料的格子保留未知，不提供配方。","instructionEn":"Use WHOI’s overview to sketch buoyancy material, frame and attachments. Compare two hypothetical materials by density, water uptake or compression behavior, and mounting interfaces. Leave unavailable data unknown and supply no formulation.","observation":"材料在表面能浮，不足以證明深水環境中功能維持。","observationEn":"Floating at the surface does not prove retained function in a deep-water environment.","failure":"把低密度視為唯一選材條件，会漏掉環境與連接需求。","failureEn":"Using low density as the sole criterion omits environment and attachment needs.","check":"至少提出一項材料性能及一項固定介面需取得的驗證證據。","checkEn":"Identify evidence needed for one material property and one attachment interface.","knowledge":[{"id":"c101-v6-05-k1","title":"功能分工","titleEn":"Functional allocation","text":"浮材提供浮力，框架與附件承擔不同的結構功能。","textEn":"Buoyancy material, frame and attachments perform different functions."},{"id":"c101-v6-05-k2","title":"環境相容","titleEn":"Environmental compatibility","text":"性能需要連同環境及使用時間定義。","textEn":"Performance must be defined together with environment and duration."}],"quiz":{"question":"桌上浮水測試能直接證明哪件事？","questionEn":"What can a tabletop flotation test directly establish?","options":["真實載人任務可用","該次表面條件下的浮水表現","所有深度下的耐久性"],"optionsEn":["Suitability for an actual crewed mission","Flotation behavior under those surface conditions","Durability at every depth"],"answer":1,"explanation":"測試結論不能超出其條件。","explanationEn":"A test conclusion cannot exceed its conditions."}},{"id":"c101-v6-06","order":2,"sequence":6,"simulationOnly":true,"estimatedMinutes":18,"prerequisiteIds":["c101-v6-05"],"sourceIds":["v6-alvin-systems"],"title":"編製科學設備能量預算","titleEn":"Budget energy for scientific equipment","objective":"區分功率需求與任務能量需求。","objectiveEn":"Distinguish power demand from mission energy demand.","instruction":"用自訂例題：相機10W開2小時，燈30W開半小時。求總Wh，再加入一項待查的待機消耗；把未知量獨立列出，不宣稱已估算整艇續航。","instructionEn":"Use an invented example: a 10 W camera for two hours and a 30 W light for half an hour. Sum Wh and add an unknown standby term separately. Do not claim to have estimated vehicle endurance.","observation":"相機用20Wh，燈用15Wh；高功率不一定意味較大總能耗。","observationEn":"The camera uses 20 Wh and the light 15 Wh; higher power need not mean higher total energy.","failure":"把W直接相加當作Wh，或漏掉待機時間，會破壞能量帳。","failureEn":"Adding watts as if they were watt-hours or omitting standby time breaks the energy balance.","check":"列出35Wh已知部分、未知待機項及單位。","checkEn":"Report the known 35 Wh subtotal, unknown standby term and units.","knowledge":[{"id":"c101-v6-06-k1","title":"功與率","titleEn":"Energy and power","text":"能量是功率對時間的累積。","textEn":"Energy accumulates power over time."},{"id":"c101-v6-06-k2","title":"預算邊界","titleEn":"Budget boundary","text":"科學負載能量不等於全部系統能量。","textEn":"Science-payload energy is not total system energy."}],"quiz":{"question":"哪個设备在此例耗能較多？","questionEn":"Which device uses more energy in this example?","options":["相機，20Wh","燈，因為30W較大","兩者相同"],"optionsEn":["Camera, 20 Wh","Light, because 30 W is larger","They use the same energy"],"answer":0,"explanation":"必須同時考慮功率與使用時間。","explanationEn":"Both power and duration matter."}},{"id":"c101-v6-07","order":3,"sequence":7,"simulationOnly":true,"estimatedMinutes":18,"prerequisiteIds":["c101-v6-06"],"sourceIds":["v6-alvin-systems"],"title":"安排照明與影像幾何","titleEn":"Arrange lighting and imaging geometry","objective":"理解照明方向與懸浮粒子對影像的影響。","objectiveEn":"Understand lighting direction and suspended-particle effects.","instruction":"畫相機、目標及兩個不同方向的燈位。用示意光線標出直接照明與可能回到鏡頭的散射路徑；比較目標對比與陰影，不把示意圖當作已取得的水下照片。","instructionEn":"Sketch a camera, target and two lighting positions. Trace direct illumination and possible particle-scattered paths into the lens. Compare contrast and shadows without treating the diagram as acquired underwater photography.","observation":"更多光不一定帶来更多可辨識細節，散射也可能增加。","observationEn":"More light does not necessarily reveal more detail; scattering may also increase.","failure":"只提高亮度而不查光路，會把曝光與可辨識度混為一談。","failureEn":"Increasing brightness without checking geometry confuses exposure with interpretability.","check":"在兩張圖上各標出一項改善及一項代價。","checkEn":"Mark one benefit and one trade-off on each diagram.","knowledge":[{"id":"c101-v6-07-k1","title":"散射","titleEn":"Scattering","text":"水中粒子可把光送回相機，降低目標對比。","textEn":"Particles can scatter light back toward the camera and reduce target contrast."},{"id":"c101-v6-07-k2","title":"幾何證據","titleEn":"Geometric evidence","text":"影像判讀需要相機、光源與目標的相對位置。","textEn":"Image interpretation benefits from relative camera, source and target positions."}],"quiz":{"question":"燈變亮但目標更難辨識，合理的下一步是？","questionEn":"The light is brighter but the target is harder to distinguish. What is a reasonable next step?","options":["只用相機的標稱像素數解釋影像品質","只繼續增加亮度，不檢查光路","檢查散射與照明幾何"],"optionsEn":["Explain quality only from the camera pixel count","Continue increasing brightness without checking optical paths","Inspect scattering and lighting geometry"],"answer":2,"explanation":"亮度與有用影像資訊不是同一量。","explanationEn":"Brightness and useful image information are not the same quantity."}},{"id":"c101-v6-08","order":4,"sequence":8,"simulationOnly":true,"estimatedMinutes":18,"prerequisiteIds":["c101-v6-07"],"sourceIds":["v6-alvin-systems","v6-alvin-verification"],"title":"檢查取樣工具的可達範圍","titleEn":"Check sampling-tool reach","objective":"把觀測視野、工具路徑與樣本容器接起來。","objectiveEn":"Connect viewing field, tool path and sample container.","instruction":"用平面示意圖放置相機視野、兩節教學手臂、樣本與容器。画取樣前後的工具姿態，检查路径是否遮住視野或碰到其他設備；不使用真機關節設定。","instructionEn":"On a plan-view schematic, place a camera field, a two-link teaching arm, a sample and a container. Draw before/after tool poses and inspect obscured views or equipment intersections, without using real joint settings.","observation":"端點能碰到樣本，不代表整段手臂路徑無衝突。","observationEn":"Reaching the sample with the endpoint does not prove the whole arm path is clear.","failure":"忽略手臂中間連桿或樣本外形，會低估碰撞範圍。","failureEn":"Ignoring intermediate links or sample shape underestimates collision extent.","check":"保留起點、過渡點及終點三個姿態，皆核對視野與空間。","checkEn":"Retain start, intermediate and end poses, checking view and clearance at each.","knowledge":[{"id":"c101-v6-08-k1","title":"可達與可行","titleEn":"Reachable and feasible","text":"幾何可達只是任務可行的必要條件之一。","textEn":"Geometric reachability is only one condition for task feasibility."},{"id":"c101-v6-08-k2","title":"樣本脈絡","titleEn":"Sample context","text":"取樣前影像與容器識別維持科學證據鏈。","textEn":"Pre-sampling imagery and container identity preserve scientific context."}],"quiz":{"question":"工具端點路徑無碰撞，還要看什麼？","questionEn":"The tool endpoint path is clear. What else must be checked?","options":["只比較起點與終點的工具位置","所有連桿及樣本的掃掠空間","只檢查空載手臂，不納入樣本外形"],"optionsEn":["Compare only initial and final tool positions","Swept space of every link and the sample","Check only the empty arm, excluding the sample shape"],"answer":1,"explanation":"碰撞可發生在端點以外的任何部分。","explanationEn":"Collision can occur on parts other than the endpoint."}}]},{"id":"c101-stage03","order":3,"title":"定位、紀錄與科學驗證","titleEn":"Positioning, records and science verification","description":"用量測模型與資料流程檢查樣本是否能連回原問題。","descriptionEn":"Use measurement models and data flows to check whether samples can be traced to the original question.","route":"原創概念學習路線；工序編號是教學順序，不是原廠連續製造或操作程序。","routeEn":"An original conceptual learning route; numbering indicates teaching order, not a continuous manufacturer production or operating procedure.","steps":[{"id":"c101-v6-09","order":1,"sequence":9,"simulationOnly":true,"estimatedMinutes":18,"prerequisiteIds":["c101-v6-08"],"sourceIds":["v6-alvin-systems"],"title":"閱讀聲學測距的不確定性","titleEn":"Read uncertainty in acoustic ranging","objective":"區分傳播時間、距離與位置估計。","objectiveEn":"Separate travel time, range and position estimation.","instruction":"假設聲速c固定、量得雙程時間t，寫出距離r=ct/2。再將時間誤差寫成±Δt，求距離誤差項；全部符號計算，不假裝提供航次數據。","instructionEn":"Assume constant sound speed c and measured round-trip time t, giving r=ct/2. Introduce timing error ±Δt and derive the range-error term. Use symbolic calculations without implying expedition data are supplied.","observation":"單一距離只限制在等距位置集合上，不能獨立決定完整位置。","observationEn":"One range constrains a set of equal-distance positions, not a complete position.","failure":"漏除以2會把雙程路徑當作單程距離。","failureEn":"Omitting division by two treats the round-trip path as one-way range.","check":"寫出r及±cΔt/2，並列出還缺的幾何或量測資訊。","checkEn":"Write r and ±cΔt/2, then list missing geometry or measurements.","knowledge":[{"id":"c101-v6-09-k1","title":"雙程時間","titleEn":"Round-trip timing","text":"發送到回收的時間包含去程與回程。","textEn":"Transmit-to-return time includes outward and return travel."},{"id":"c101-v6-09-k2","title":"量測到定位","titleEn":"Measurement to position","text":"定位需要足夠幾何約束，也受環境模型影響。","textEn":"Positioning requires sufficient geometric constraints and depends on environmental models."}],"quiz":{"question":"用雙程時間求單程距離，為何除以2？","questionEn":"Why divide round-trip travel time by two when finding one-way range?","options":["聲音走了來回兩段","為了把時鐘誤差直接減半","為了補償往返的聲能損失"],"optionsEn":["The sound travels outward and back","To halve the clock error directly","To compensate for acoustic energy lost on the return trip"],"answer":0,"explanation":"距離為 r=ct/2；聲速固定時，時間誤差對應距離誤差 ±cΔt/2。雙程時間包含去程與回程，除以2是路徑換算，不是消除時鐘誤差。","explanationEn":"Range is r=ct/2. With fixed sound speed, a time error gives range error ±cΔt/2. Round-trip time includes outward and return paths; dividing by two converts path length, not clock error."}},{"id":"c101-v6-10","order":2,"sequence":10,"simulationOnly":true,"estimatedMinutes":18,"prerequisiteIds":["c101-v6-09"],"sourceIds":["v6-alvin-systems"],"title":"建立水下訊息的確認流程","titleEn":"Build an underwater-message acknowledgment flow","objective":"在有限通訊下分辨已送出與已收到。","objectiveEn":"Distinguish sent from received under constrained communication.","instruction":"為虛構科學任務畫三個訊息狀態：待送、已送、已確認。给影像摘要加序號與時間；假設一則確認遺失，安排重傳時如何避免重複記錄。","instructionEn":"Create pending, sent and acknowledged states for a fictional science message. Add sequence and time to an image summary. Assume an acknowledgment is lost and specify how retransmission avoids duplicate records.","observation":"發送端沒有確認，不等於接收端一定沒收到。","observationEn":"Lack of acknowledgment does not prove the receiver got nothing.","failure":"重傳訊息沒有識別碼，可能被當作第二筆觀測。","failureEn":"Retransmission without an identifier may be mistaken for a second observation.","check":"用同一序號演練一次確認遺失，接收紀錄只保留一筆邏輯資料。","checkEn":"Walk through one lost acknowledgment using the same sequence ID, retaining one logical record.","knowledge":[{"id":"c101-v6-10-k1","title":"通訊狀態","titleEn":"Communication state","text":"傳送成功、接收成功與應用處理完成並不相同。","textEn":"Transmission, reception and application processing are distinct successes."},{"id":"c101-v6-10-k2","title":"冪等處理","titleEn":"Idempotent handling","text":"重複收到同一識別訊息，不應重複產生相同資料事件。","textEn":"Receiving the same identified message repeatedly should not duplicate its data event."}],"quiz":{"question":"確認遺失後重傳，最有用的欄位是？","questionEn":"Which field is most useful when retransmitting after a lost acknowledgment?","options":["每次重傳都產生新的訊息識別碼","只依接收時間判斷是否重複","穩定的訊息識別碼"],"optionsEn":["Generate a new message identifier for every retransmission","Determine duplicates solely from reception time","A stable message identifier"],"answer":2,"explanation":"穩定識別有助於區分重傳與新資料。","explanationEn":"Stable identity distinguishes retransmission from new data."}},{"id":"c101-v6-11","order":3,"sequence":11,"simulationOnly":true,"estimatedMinutes":18,"prerequisiteIds":["c101-v6-10"],"sourceIds":["v6-alvin-verification"],"title":"核對影像、樣本與時間鏈","titleEn":"Reconcile image, sample and time records","objective":"讓不同設備資料能對應同一事件。","objectiveEn":"Associate records from different devices with one event.","instruction":"自製三筆示意觀測，記錄相機時間、採样時間及樣本編號。刻意讓一台時鐘快2分鐘，計算校正後配對，再保留原始時間與校正說明。","instructionEn":"Create three synthetic observations with camera time, sampling time and sample ID. Make one clock two minutes fast, pair events after correction, and retain raw times and the correction note.","observation":"時間一致應指同一基準，而非只看數字接近。","observationEn":"Time consistency means a common reference, not merely similar numbers.","failure":"直接覆寫原始時間會失去重建判讀過程的線索。","failureEn":"Overwriting raw timestamps removes evidence needed to reconstruct interpretation.","check":"每組配對能追到原始紀錄、時間偏移與樣本識別。","checkEn":"Trace each pairing to raw records, clock offset and sample identity.","knowledge":[{"id":"c101-v6-11-k1","title":"溯源","titleEn":"Provenance","text":"保留原始值與處理步驟，才能重現結果。","textEn":"Retaining raw values and processing steps enables reproducibility."},{"id":"c101-v6-11-k2","title":"同步誤差","titleEn":"Synchronization error","text":"設備時鐘偏差可能造成事件錯配。","textEn":"Clock offsets can misassociate events."}],"quiz":{"question":"發現固定2分鐘偏差，較好的紀錄方法是？","questionEn":"A constant two-minute offset is discovered. What is the better record practice?","options":["忽略偏差只看檔案順序","保留原始時間並另存校正值與方法","直接覆寫所有原始時間"],"optionsEn":["Ignore it and rely on file order","Keep raw time and separately record corrected time and method","Overwrite all raw timestamps"],"answer":1,"explanation":"分開保存原始與處理後資料可重建證據鏈。","explanationEn":"Keeping raw and processed data separately preserves the evidence chain."}},{"id":"c101-v6-12","order":4,"sequence":12,"simulationOnly":true,"estimatedMinutes":18,"prerequisiteIds":["c101-v6-11"],"sourceIds":["v6-alvin-history","v6-alvin-systems","v6-alvin-verification"],"title":"區分工程驗證與科學驗證","titleEn":"Separate engineering and science verification","objective":"把平台可用與資料可用分成不同證據。","objectiveEn":"Separate platform readiness from data usability.","instruction":"閱讀WHOI的2022年科學驗證公開說明。將本課程成果分成平台概念、工具功能及資料品質三欄，為每欄寫一項已完成紙上檢查與一項仍需專業實測的問題。","instructionEn":"Read WHOI’s public account of 2022 science verification. Sort course outcomes into platform concepts, tool functions and data quality, giving one completed paper check and one question requiring professional measurement in each.","observation":"平台完成某項測試，並不自動證明所有樣本與影像符合科學目的。","observationEn":"Passing one platform test does not automatically establish that all samples and images meet scientific goals.","failure":"將公開認證深度當作本課程模型的操作許可，是範圍錯置。","failureEn":"Treating a publicly reported depth certification as operating permission for a teaching model is a scope error.","check":"交付三欄驗證表，清楚標示本課程只完成教育分析。","checkEn":"Deliver the three-column matrix, clearly identifying the work as educational analysis only.","knowledge":[{"id":"c101-v6-12-k1","title":"分層驗證","titleEn":"Layered verification","text":"系統安全、工具功能與資料適用性需要各自的證據。","textEn":"System safety, tool function and data fitness need their own evidence."},{"id":"c101-v6-12-k2","title":"科學可用性","titleEn":"Scientific usability","text":"資料必須能回答原定問題，才算有用的觀測。","textEn":"Data must answer the intended question to be a useful observation."}],"quiz":{"question":"工具動作正常，但樣本標籤混亂，哪項仍未通過？","questionEn":"The tool works, but sample labels are confused. Which aspect remains unverified?","options":["科學資料的可追溯性","工具一定無法移動","所有工程测试均失敗"],"optionsEn":["Scientific-data traceability","The tool necessarily cannot move","Every engineering test has failed"],"answer":0,"explanation":"功能正常與資料追溯是不同驗證項。","explanationEn":"Functional operation and data traceability are distinct checks."}}]}],"stepCount":12,"estimatedMinutes":216,"languageCoverage":["zh-TW","en"],"status":"guided","kind":"course","curriculumVersion":6}};
